package com.kuaixietech.integrationsdk.social;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.fasterxml.jackson.databind.*;
import com.kuaixietech.integration.IntegrationHttp;
import com.kuaixietech.security.DomainAccessGuard;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.zip.InflaterInputStream;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;
class SocialProtocolSafetyTest {
 final ObjectMapper json=new ObjectMapper();final IntegrationHttp http=mock(IntegrationHttp.class);final Clock clock=Clock.fixed(Instant.parse("2026-11-01T00:00:00Z"),ZoneOffset.UTC);
 static final String USER="11111111-1111-1111-1111-111111111111",OTHER="22222222-2222-2222-2222-222222222222",STRANGER="33333333-3333-3333-3333-333333333333",SECRET="0123456789abcdef0123456789abcdef";
 SocialServiceContext mini(String category,String mode,long revision,String secret){return new SocialServiceContext(category,"weixin",mode,Map.of("app_id","wx1234567890abcdef","app_secret",secret,"template_id","template_123"),revision);}
 SocialServiceContext rtc(String mode){return new SocialServiceContext("RTC","tencent",mode,Map.of("sdk_app_id","1400000001","secret_key",SECRET,"usersig_ttl_seconds","300","advanced_permission_control","true"),1);}
 WechatMiniProtocol wechat(){return new WechatMiniProtocol(http,json,clock);}
 @Test void wechatHasNoSandboxFallback(){var protocol=wechat();assertThrows(IllegalStateException.class,()->protocol.session(mini("MINIAPP","SANDBOX",1,"secret"),"code1234"));assertThrows(IllegalStateException.class,()->protocol.subscribe(mini("SUBSCRIBE","SANDBOX",1,"secret"),new WechatMiniProtocol.Recipient("wx1234567890abcdef","openid123"),null,Map.of("thing1","hello"),"zh_CN",true));verifyNoInteractions(http);}
 @Test void wechatLoginRejectsProviderErrorsAndMissingIdentity(){var p=wechat();when(http.send(any())).thenReturn("{\"errcode\":40029}","{\"session_key\":\"secret\"}");assertThrows(IllegalStateException.class,()->p.session(mini("MINIAPP","LIVE",1,"secret"),"code1234"));assertThrows(IllegalStateException.class,()->p.session(mini("MINIAPP","LIVE",1,"secret"),"code1234"));}
 @Test void miniSessionDoesNotExposeSessionKey(){when(http.send(any())).thenReturn("{\"openid\":\"openid123\",\"session_key\":\"provider-secret\"}");var session=wechat().session(mini("MINIAPP","LIVE",1,"secret"),"code1234");assertEquals("openid123",session.openId());assertFalse(session.toString().contains("openid123"));assertFalse(session.toString().contains("provider-secret"));}
 @Test void subscriptionNeedsConsentAndSameAppRecipientBeforeNetwork(){var p=wechat();var ctx=mini("SUBSCRIBE","LIVE",1,"secret");assertThrows(IllegalArgumentException.class,()->p.subscribe(ctx,new WechatMiniProtocol.Recipient("wx1234567890abcdef","openid123"),null,Map.of("thing1","hi"),"zh_CN",false));assertThrows(IllegalArgumentException.class,()->p.subscribe(ctx,new WechatMiniProtocol.Recipient("wxotherappid1234","openid123"),null,Map.of("thing1","hi"),"zh_CN",true));verifyNoInteractions(http);}
 @Test void stableTokenCacheIsSeparatedByRevisionAndSecret(){when(http.send(any())).thenAnswer(c->{java.net.http.HttpRequest request=c.getArgument(0);return request.uri().getPath().endsWith("stable_token")?"{\"access_token\":\"token123\",\"expires_in\":7200}":"{\"errcode\":0}";});var p=wechat();var recipient=new WechatMiniProtocol.Recipient("wx1234567890abcdef","openid123");for(var ctx:List.of(mini("SUBSCRIBE","LIVE",1,"secret1"),mini("SUBSCRIBE","LIVE",1,"secret1"),mini("SUBSCRIBE","LIVE",2,"secret1"),mini("SUBSCRIBE","LIVE",2,"secret2")))assertTrue(p.subscribe(ctx,recipient,null,Map.of("thing1","hi"),"zh_CN",true).accepted());var requests=org.mockito.ArgumentCaptor.forClass(java.net.http.HttpRequest.class);verify(http,times(7)).send(requests.capture());assertEquals(3,requests.getAllValues().stream().filter(r->r.uri().getPath().endsWith("stable_token")).count());}
 @Test void contextSnapshotIsImmutableAndRedacted()throws Exception{var values=new HashMap<>(Map.of("app_secret","secret-value"));var context=new SocialServiceContext("MINIAPP","weixin","LIVE",values,1);values.put("app_secret","mutated");assertEquals("secret-value",context.required("app_secret"));assertThrows(UnsupportedOperationException.class,()->context.values().put("app_secret","changed"));assertFalse(context.toString().contains("secret-value"));assertFalse(json.writeValueAsString(context).contains("secret-value"));}
 JsonNode decode(String token)throws Exception{byte[] compressed=Base64.getDecoder().decode(token.replace('*','+').replace('-','/').replace('_','='));try(var stream=new InflaterInputStream(new ByteArrayInputStream(compressed))){return json.readTree(stream.readAllBytes());}}
 @Test void rtcTokensBindExactUserAppExpiryAndAudioRoomPrivileges()throws Exception{var c=new TencentRtcUserSig(json,clock).issue(rtc("LIVE"),"buyer_1","order_room_2");assertFalse(c.recordingEnabled());assertEquals(15,c.privileges());JsonNode doc=decode(c.privateMapKey());assertEquals("buyer_1",doc.path("TLS.identifier").asText());assertEquals(1400000001L,doc.path("TLS.sdkappid").asLong());assertEquals(300,doc.path("TLS.expire").asInt());assertEquals(clock.instant().getEpochSecond(),doc.path("TLS.time").asLong());assertFalse(decode(c.userSig()).has("TLS.userbuf"));String canonical="TLS.identifier:buyer_1\nTLS.sdkappid:1400000001\nTLS.time:"+clock.instant().getEpochSecond()+"\nTLS.expire:300\nTLS.userbuf:"+doc.path("TLS.userbuf").asText()+"\n";var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(SECRET.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));assertEquals(Base64.getEncoder().encodeToString(mac.doFinal(canonical.getBytes(StandardCharsets.UTF_8))),doc.path("TLS.sig").asText());try(var data=new DataInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(doc.path("TLS.userbuf").asText())))){assertEquals(1,data.readUnsignedByte());assertEquals("buyer_1",new String(data.readNBytes(data.readUnsignedShort()),StandardCharsets.US_ASCII));assertEquals(1400000001L,Integer.toUnsignedLong(data.readInt()));assertEquals(0,data.readInt());assertEquals(clock.instant().getEpochSecond()+300,Integer.toUnsignedLong(data.readInt()));assertEquals(15,data.readInt());assertEquals(0,data.readInt());assertEquals("order_room_2",new String(data.readNBytes(data.readUnsignedShort()),StandardCharsets.US_ASCII));assertEquals(-1,data.read());}assertFalse(c.toString().contains(c.userSig()));}
 @Test void rtcRejectsSandboxUnscopedControlAndExcessiveLifetime(){var issuer=new TencentRtcUserSig(json,clock);assertThrows(IllegalStateException.class,()->issuer.issue(rtc("SANDBOX"),"buyer","room"));for(String field:List.of("advanced_permission_control","usersig_ttl_seconds")){var values=new HashMap<>(rtc("LIVE").values());values.put(field,field.equals("advanced_permission_control")?"false":"3600");assertThrows(RuntimeException.class,()->issuer.issue(new SocialServiceContext("RTC","tencent","LIVE",values,1),"buyer","room"));}assertThrows(IllegalArgumentException.class,()->issuer.issue(rtc("LIVE"),"buyer","room/escape"));}
 Map<String,Object> call(String status,String order){return Map.of("caller_id",USER,"callee_id",OTHER,"status",status,"room_id","server_room","buyer_id",USER,"vendor_id",OTHER,"order_status",order);}
 @Test void rtcOnlyAcceptedActiveOrderParticipantsCanGetServerRoom(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);var issuer=mock(TencentRtcUserSig.class);var service=new TencentRtcOrderCredentials(db,guard,issuer);when(guard.requireActiveProfile()).thenReturn(USER);when(db.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(call("accepted","locked")));service.forAcceptedCall(rtc("LIVE"),"call1");verify(issuer).issue(any(),eq(USER.replace("-","")),eq("server_room"));}
 @Test void rtcStrangersAndPendingOrFinishedCallsGetNoTokens(){for(var row:List.of(call("pending","locked"),call("accepted","finished"),call("cancelled","locked"))){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);var issuer=mock(TencentRtcUserSig.class);when(guard.requireActiveProfile()).thenReturn(USER);when(db.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(row));assertThrows(ResponseStatusException.class,()->new TencentRtcOrderCredentials(db,guard,issuer).forAcceptedCall(rtc("LIVE"),"call1"));verifyNoInteractions(issuer);}var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);var issuer=mock(TencentRtcUserSig.class);when(guard.requireActiveProfile()).thenReturn(STRANGER);when(db.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(call("accepted","locked")));assertThrows(ResponseStatusException.class,()->new TencentRtcOrderCredentials(db,guard,issuer).forAcceptedCall(rtc("LIVE"),"call1"));verifyNoInteractions(issuer);}
 @Test void callPartyMustAlsoBelongToTheAssociatedOrder(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);var issuer=mock(TencentRtcUserSig.class);var row=new HashMap<String,Object>(call("accepted","locked"));row.put("buyer_id",STRANGER);when(guard.requireActiveProfile()).thenReturn(USER);when(db.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(row));assertThrows(ResponseStatusException.class,()->new TencentRtcOrderCredentials(db,guard,issuer).forAcceptedCall(rtc("LIVE"),"call1"));verifyNoInteractions(issuer);}

}
